const base=new URL('../',document.currentScript.src).pathname;const link=p=>base+p;const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;let paused=reduced;const route=location.pathname.slice(base.length).split('/')[0];const page=['work','about','contact'].includes(route)?route:'home';
const stops=[{path:'',name:'Home',no:'00',description:'You are here'},{path:'work/',name:'Selected work',no:'01',description:'Ideas made tangible'},{path:'about/',name:'Behind Athetis',no:'02',description:'Meet the person'},{path:'contact/',name:'Make a connection',no:'03',description:'Start a conversation'}];
const projects=[{id:'openedmind',name:'OpenedMind',category:'Digital',tag:'Behavioral science / Technology',description:'An exploration of technology and mental health, bringing emotion recognition and conversational support into one digital experience.',detail:'Built around a simple question: how can technology respond more thoughtfully to people? OpenedMind connects my interest in psychology with the process of designing and building digital tools.',url:'https://openedmind.org',label:'Visit OpenedMind'},{id:'visual',name:'Visual studies',category:'Visual',tag:'Art direction / Experiments',description:'A space for photography, typography and the things that catch my eye.',detail:'This archive is ready for new work: images, compositions and experiments in the way a story feels before a single word is read. Individual studies will be added here.',status:'Archive in progress'},{id:'writing',name:'Words in transit',category:'Writing',tag:'Poetry / Reflections',description:'Notes on people, places and the moments in between.',detail:'A place for poems, personal reflections and short pieces. The writing archive is taking shape; new pieces will appear here.',status:'Archive in progress'}];
function header(){return `<header><a class="wordmark" href="${base}" aria-label="Athetis home">Athetis<span>A PERSONAL PLATFORM</span></a><nav aria-label="Main navigation">${['work','about','contact'].map((p,i)=>`<a class="${page===p?'active':''}" href="${link(p+'/')}"><span class="nav-num">0${i+1}</span>${p[0].toUpperCase()+p.slice(1)}</a>`).join('')}</nav></header>`}
function footer(){return `<footer><span>ATHETIS © ${new Date().getFullYear()} / ALL JOURNEYS WELCOME.</span><button class="motion-toggle" id="motion">${paused?'Resume motion':'Pause motion'}</button><span>INDEPENDENT. ALWAYS IN MOTION.</span></footer><div class="transition" aria-hidden="true"><span id="transition-label">Next stop</span></div>`}
function board(){return `<section class="announcement" aria-label="Athetis departure board"><div class="departure-board"><div class="board-head"><span>ATHETIS / DEPARTURES</span><span>PLATFORM A</span></div><div class="board-announcement" id="announcement">Next stop your next idea</div><div class="board-labels"><span>TIME</span><span>DESTINATION</span><span>STOP</span></div><div class="destinations">${stops.slice(1).map((s,i)=>`<a class="departure" href="${link(s.path)}"><span class="time" data-time="${i*3}">—</span><span class="place">${['Selected work','About Athetis','Contact'][i]}</span><span class="platform">${s.no}</span></a>`).join('')}</div><div class="board-footer">Calling at: creativity, curiosity, connection.<br>All destinations open. No ticket required.</div></div><aside class="route-panel"><div class="eyebrow">The personal line</div><h2>Find your stop</h2><div class="journey-map">${stops.map(s=>`<a class="journey-stop" href="${link(s.path)}"><div><strong>${s.name}</strong><small>${s.description}</small></div><span class="stop-num">${s.no}</span></a>`).join('')}</div><a class="button" href="${link('work/')}">Explore the work</a></aside></section>`}
function rows(filter='All'){return projects.filter(p=>filter==='All'||p.category===filter).map((p,i)=>`<div class="project-entry"><button class="project-row" data-project="${p.id}" aria-expanded="false" aria-controls="detail-${p.id}"><span class="project-index">0${projects.indexOf(p)+1}</span><h3>${p.name}</h3><span class="category">${p.tag}</span><span class="open">VIEW +</span></button><div class="project-detail" id="detail-${p.id}" hidden><p class="display">${p.name}</p><p>${p.description}</p><p>${p.detail}</p>${p.url?`<a class="button outline external" href="${p.url}" target="_blank" rel="noopener noreferrer">${p.label}</a>`:`<span class="micro">${p.status.toUpperCase()}</span>`}</div></div>`).join('')}
function atmosphere(){return `<section class="atmosphere"><img src="${link('assets/platform.webp')}" width="1536" height="1024" alt="An amber-lit underground platform with an arriving train" loading="lazy"><div class="atmosphere-copy"><div class="eyebrow">Between destinations</div><h2>Keep moving<br>Stay curious</h2><p>Athetis is where my interests meet: people, technology, words and the way we see the world.</p><div><a href="${link('about/')}" class="text-link">Behind the name</a></div></div></section>`}
function home(){return `<main><div class="hero-top"><div class="eyebrow station-sign"><span class="route-badge">A</span>Independent ideas / Personal platform</div><time class="clock" id="clock"></time></div><section class="hero"><h1>Athetis</h1><div class="hero-bottom"><p class="hero-copy">A platform for what comes next.<br><span>Ideas, stories, and work by Amaury.</span></p><div class="micro">ARRIVE WITH CURIOSITY.<br>LEAVE WITH SOMETHING NEW.</div></div></section>${board()}<div class="track-ticker" aria-hidden="true"><div class="track"><span class="train-light"></span></div><span>Next stop creativity &nbsp; / &nbsp; Next stop curiosity &nbsp; / &nbsp; Next stop connection &nbsp; / &nbsp; Next stop creativity &nbsp; / &nbsp; Next stop curiosity &nbsp; / &nbsp; Next stop connection &nbsp; / &nbsp;</span></div><div class="section-head"><h2>On the platform</h2><a class="text-link" href="${link('work/')}">All work</a></div><section class="project-list" aria-label="Selected projects">${rows()}</section>${atmosphere()}</main>`}
function heading(no,title,copy){return `<div class="page-heading"><div class="eyebrow station-sign"><span class="route-badge">A</span>Station ${no} / Athetis</div><h1>${title}</h1><p>${copy}</p></div>`}
function work(){return `<main>${heading('01','Selected work','Digital projects, visual experiments, and words. Different tracks, the same curiosity.')}<div class="filters" role="group" aria-label="Filter projects">${['All','Digital','Visual','Writing'].map(f=>`<button class="filter ${f==='All'?'active':''}" data-filter="${f}" aria-pressed="${f==='All'}">${f}</button>`).join('')}</div><section class="project-list" id="project-list" aria-label="Projects">${rows()}</section><div class="micro" style="margin-bottom:55px">AN OPEN ARCHIVE / MORE ARRIVALS TO COME.</div></main>`}
function about(){return `<main>${heading('02','Behind Athetis','A personal platform. A place to bring different parts of my world together.')}<div class="about-grid"><section><h2>Hello Im Amaury</h2><p>I’m interested in people: how we think, how we connect, and how the things we make can help us understand one another.</p><p>That curiosity leads me in a few directions. Sometimes it becomes a digital project. Sometimes an image, a piece of writing, or a new question.</p><p>Athetis gives those ideas a home. It’s an ongoing collection of the work I’m making and the things I’m learning along the way.</p><a class="text-link" href="${link('contact/')}">Let’s connect</a></section><aside class="about-stats"><div class="eyebrow">Lines of interest</div><div class="about-stat"><div class="display">People first</div><p>Psychology, connection, and the human side of technology.</p></div><div class="about-stat"><div class="display">Make something</div><p>Turning a question into something you can see, read, or use.</p></div><div class="about-stat"><div class="display">Keep exploring</div><p>Room for experiments, new perspectives, and unexpected stops.</p></div></aside></div>${atmosphere()}</main>`}
function contact(){return `<main>${heading('03','Make a connection','Have an idea, a question, or something you think I should see? Let’s talk.')}<section class="contact-card"><div><h2>The next stop<br>Could be yours</h2><p>Find me online to start a conversation, follow what I’m working on, or take a closer look at the code.</p><div class="eyebrow">NO WRONG CONNECTIONS.</div></div><div class="contact-links"><a class="external" href="https://www.instagram.com/amauryca_/" target="_blank" rel="noopener noreferrer">Instagram<span>@amauryca_</span></a><a class="external" href="https://github.com/amauryca" target="_blank" rel="noopener noreferrer">GitHub<span>@amauryca</span></a><a href="${link('work/')}">Explore the work<span>STATION 01</span></a></div></section></main>`}
const titles={home:'Athetis — A personal platform',work:'Selected work — Athetis',about:'Behind Athetis — Athetis',contact:'Make a connection — Athetis'};document.title=titles[page];document.getElementById('app').innerHTML=header()+({home,work,about,contact}[page]())+footer();document.body.classList.toggle('paused',paused);
function bindProjects(){document.querySelectorAll('[data-project]').forEach(b=>b.addEventListener('click',()=>{const expanded=b.getAttribute('aria-expanded')==='true';b.setAttribute('aria-expanded',String(!expanded));document.getElementById('detail-'+b.dataset.project).hidden=expanded;b.querySelector('.open').textContent=expanded?'VIEW +':'CLOSE −'}))}bindProjects();document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('[data-filter]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',String(x===b))});document.getElementById('project-list').innerHTML=rows(b.dataset.filter);bindProjects()}));
document.getElementById('motion').addEventListener('click',e=>{paused=!paused;document.body.classList.toggle('paused',paused);e.target.textContent=paused?'Resume motion':'Pause motion'});
function clock(){const now=new Date();const el=document.getElementById('clock');if(el)el.textContent=now.toLocaleTimeString([],{hour:'2-digit',minute:'2-digit',hour12:false})+' / LOCAL TIME';document.querySelectorAll('[data-time]').forEach(el=>{const t=new Date(now.getTime()+Number(el.dataset.time)*60000);el.textContent=t.toLocaleTimeString([],{hour:'2-digit',minute:'2-digit',hour12:false})})}clock();setInterval(clock,10000);
const announcements=['Next stop your next idea','Calling at creativity','All journeys welcome','Athetis now boarding'];let announcementIndex=0;setInterval(()=>{if(paused)return;const el=document.getElementById('announcement');if(el)el.textContent=announcements[++announcementIndex%announcements.length]},4500);
document.addEventListener('click',e=>{const a=e.target.closest('a');if(!a||e.defaultPrevented||e.button!==0||e.metaKey||e.ctrlKey||e.shiftKey||e.altKey||a.target||paused||reduced)return;const u=new URL(a.href);if(u.origin!==location.origin||!u.pathname.startsWith(base)||u.pathname===location.pathname)return;e.preventDefault();document.getElementById('transition-label').textContent='Next stop '+(u.pathname.endsWith('work/')?'Selected work':u.pathname.endsWith('about/')?'Athetis':u.pathname.endsWith('contact/')?'Connection':'Home');document.querySelector('.transition').classList.add('active');setTimeout(()=>location.assign(a.href),620)});
